    slug: "trockner-was-darf-rein-pflegesymbole",
    title: "Was darf in den Trockner? Die wichtigsten Regeln und Symbole",
    titleTag: "Was darf in den Trockner? Symbole & Tipps",
    metaDescription: "Was darf in den Trockner und was nicht? Trocknersymbole erklärt, Stoffe die einlaufen und Tipps zu Beladung, Dauer und Flusensieb – auch im Waschsalon.",
    category: "Waschsalon-Ratgeber",
    author: "Waschbar Team",
    date: "2026-10-24",
    primaryKeyword: "was darf in den trockner",
    intent: "informational",
    heroImage: "/images/waschbar-faq-dryers-real.webp",
    heroImageAlt: "Trocknerwand mit Dry-Beschriftung im Waschbar Waschsalon",
